const APP={screen:'menu',save:loadSave(),settings:loadSettings(),selectedSlot:null,currentId:null,map:null,tiles:null,sprites:null,worldReady:false,raf:null,lastFrame:0,camera:{x:0,y:0},canvas:null,ctx:null,miniCanvas:null,keys:new Set(),moveTarget:null,navPath:[],navDestination:null,navRepathAt:0,navBlockedFor:0,pendingInteraction:null,selectedObjectId:null,panelTab:'inventory',installPrompt:null,swRegistration:null,combat:{enemyId:null,lastPlayerHit:0,lastEnemyHit:0,flourishReadyAt:0,guardReadyAt:0,guardUntil:0,riposteUntil:0,telegraph:null},motion:{actors:{},floaters:[],particles:[],chatter:null,nextChatter:0,lastStep:0,playerMoving:false,worldTime:0,lastClockMinute:-1,lastTimeSave:0},log:'Welcome to Port Felin.',create:{name:'',appearance:'orange',background:'duelist'}};
const APPEARANCES={orange:{label:'Orange Tabby',sprite:0,portrait:'assets/world/portrait_orange.png'},tuxedo:{label:'Tuxedo',sprite:1,portrait:'assets/world/portrait_tuxedo.png'},gray:{label:'Silver Gray',sprite:2,portrait:'assets/world/portrait_gray.png'}};
const BACKGROUNDS={
 duelist:{label:"Duelist's Page",desc:'Begins with stronger Fencing and a worn rapier.',bonuses:{fencing:1},items:{bread:2,healing_tonic:1},equipment:{weapon:'worn_rapier'}},
 artisan:{label:'Guild Artisan',desc:'Begins with stronger Smithing and useful materials.',bonuses:{smithing:1,crafting:1},items:{iron_ore:2,oak_log:2,bread:1},equipment:{weapon:'work_knife'}},
 mouser:{label:'Country Mouser',desc:'Begins with stronger Foraging and Woodcutting.',bonuses:{foraging:1,woodcutting:1},items:{rosemary:2,bread:3},equipment:{weapon:'hunting_knife'}}
};
const ITEMS={
 bread:{name:'Brown Bread',icon:'🥖',desc:'Restores 8 health.',value:3,use:'heal',amount:8},healing_tonic:{name:'Red Tonic',icon:'🧪',desc:'Restores 20 health.',value:12,use:'heal',amount:20},
 rosemary:{name:'Rosemary',icon:'🌿',desc:'Aromatic herb used by apothecaries.',value:2},reed:{name:'River Reed',icon:'🌾',desc:'Fiber for cord and baskets.',value:2},grape:{name:'Black Grape',icon:'🍇',desc:'Tart vineyard fruit.',value:2},oak_log:{name:'Oak Log',icon:'🪵',desc:'Stout crafting timber.',value:4},iron_ore:{name:'Iron Ore',icon:'⛏',desc:'Ore for smithing.',value:7},river_dace:{name:'Silver Dace',icon:'🐟',desc:'A small river fish. Better after a turn over the inn fire.',value:4},grilled_dace:{name:'Grilled Silver Dace',icon:'🍢',desc:'Hot river fish with herbs. Restores 14 health.',value:9,use:'heal',amount:14},
 worn_rapier:{name:'Worn Rapier',icon:'🗡',desc:'A serviceable old dueling blade.',attack:2,value:8},work_knife:{name:'Work Knife',icon:'🔪',desc:'A stout guild knife.',attack:1,value:6},hunting_knife:{name:'Hunting Knife',icon:'🔪',desc:'A light country blade.',attack:1,value:6},iron_rapier:{name:'Iron Rapier',icon:'⚔',desc:'A balanced Port Felin rapier.',attack:5,value:38},padded_doublet:{name:'Padded Doublet',icon:'🧥',desc:'Quilted protection under fine cloth.',defense:2,value:28},fox_pelt:{name:'Red Fox Pelt',icon:'🦊',desc:'A fine rust-red pelt taken from an Eastroad brigand.',value:13},tempered_rapier:{name:'Tempered Rapier',icon:'⚔',desc:'A guild-tempered rapier made for dangerous roads.',attack:8,value:78},brigandine_doublet:{name:'Brigandine Doublet',icon:'🛡',desc:'Riveted plates hidden beneath a fashionable doublet.',defense:4,value:88},bandit_sash:{name:'Bandit Sash',icon:'🧣',desc:'A faded sash cut from a South Road outlaw. Neri buys these.',value:7},boar_tusk:{name:'Bristleback Tusk',icon:'🦷',desc:'A heavy tusk prized by carvers and apothecaries.',value:9}
};
