function updateNavigation(dt,now){const c=current(),dest=APP.navDestination;if(dest?.targetId&&now>=APP.navRepathAt){const o=objectById(dest.targetId);if(o){const p=objectCenter(o);if(dist(p.x,p.y,dest.x,dest.y)>20){dest.x=p.x;dest.y=p.y;replanNavigation(now)}else APP.navRepathAt=now+250}else clearNavigation(false)}if(!APP.moveTarget&&APP.navPath.length)APP.moveTarget=APP.navPath.shift();if(!APP.moveTarget)return;const d=dist(c.position.x,c.position.y,APP.moveTarget.x,APP.moveTarget.y);if(d<5){APP.moveTarget=APP.navPath.shift()||null;if(!APP.moveTarget&&!APP.navPath.length&&APP.navDestination&&!APP.navDestination.targetId){APP.navDestination=null;saveCharacter()}return}const step=Math.min(d,165*dt),moved=movePlayer((APP.moveTarget.x-c.position.x)/d*step,(APP.moveTarget.y-c.position.y)/d*step);if(moved)APP.navBlockedFor=0;else{APP.navBlockedFor+=dt;if(APP.navBlockedFor>.18&&APP.navDestination)replanNavigation(now)}}
function chooseWanderTarget(m,radius){for(let tries=0;tries<8;tries++){const ang=Math.random()*Math.PI*2,rad=Math.random()*radius,nx=m.homeX+Math.cos(ang)*rad,ny=m.homeY+Math.sin(ang)*rad;if(isWalkable(nx,ny)&&!hitsBuilding(nx,ny)){m.targetX=nx;m.targetY=ny;return}}m.targetX=m.homeX;m.targetY=m.homeY}
