function updateEffects(dt){for(const f of APP.motion.floaters){f.life-=dt;f.y-=26*dt}APP.motion.floaters=APP.motion.floaters.filter(f=>f.life>0);for(const p of APP.motion.particles){if(p.ambient){p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x>APP.map.width*64+20)p.x=-20;continue}p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=72*dt}APP.motion.particles=APP.motion.particles.filter(p=>p.ambient||p.life>0)}
